5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects -> clients foreign key: H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the truncate and restore it immediately after.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
48	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
49	        // The dashboard's fixed "as of" reference date (Flyway V23) — nothing references it, so a
50	        // plain truncate clears the single row each spec seeds.
51	        jdbc.execute("TRUNCATE TABLE app_clock");
52	    }
53	
54	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
55	    @PostMapping("/seed")
56	    @SuppressWarnings("unchecked")
57	    public void seed(@RequestBody Map<String, Object> fixture) {
58	        // asOf is the fixed reference date the dashboard measures "overdue" against (Flyway V23). A
59	        // spec seeds one so the overdue count is deterministic; stored as the single app_clock row.
60	        Object asOf = fixture.get("asOf");
61	        if (asOf != null) {
62	            jdbc.update("INSERT INTO app_clock (id, as_of) VALUES (1, ?)",
63	                    java.sql.Date.valueOf(asOf.toString()));
64	        }
65	        List<Map<String, Object>> clients = (List<Map<String, Object>>) fixture.get("clients");
66	        if (clients != null) {
67	            for (Map<String, Object> client : clients) {
68	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
69	                jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
70	                        ((Number) client.get("id")).longValue(), client.get("name"),
71	                        client.get("email"));
72	            }
73	        }
74	        List<Map<String, Object>> projects = (List<Map<String, Object>>) fixture.get("projects");
75	        if (projects != null) {
76	            for (Map<String, Object> project : projects) {
77	                // status is optional in a fixture; default to ACTIVE (matching Flyway V21) when absent.
78	                Object status = project.get("status");
79	                // archived is optional; default to false (matching Flyway V15) when absent.
80	                Object archived = project.get("archived");
81	                // budget is optional; a project without one has no budget set (NULL, Flyway V22).
82	                Object budget = project.get("budget");
83	                jdbc.update("INSERT INTO projects (id, name, client_id, status, archived, budget)"
84	                        + " VALUES (?, ?, ?, ?, ?, ?)",
85	                        ((Number) project.get("id")).longValue(), project.get("name"),
86	                        ((Number) project.get("clientId")).longValue(),
87	                        status != null ? status.toString() : "ACTIVE",
88	                        archived != null && Boolean.parseBoolean(archived.toString()),
89	                        budget != null ? new java.math.BigDecimal(budget.toString()) : null);
90	            }
91	        }
92	        List<Map<String, Object>> contacts = (List<Map<String, Object>>) fixture.get("contacts");
93	        if (contacts != null) {
94	            for (Map<String, Object> contact : contacts) {
95	                jdbc.update("INSERT INTO contacts (id, client_id, name, email, contact_role)"
96	                        + " VALUES (?, ?, ?, ?, ?)",
97	                        ((Number) contact.get("id")).longValue(),
98	                        ((Number) contact.get("clientId")).longValue(), contact.get("name"),
99	                        contact.get("email"), contact.get("role"));
100	            }
101	        }
102	        List<Map<String, Object>> tasks = (List<Map<String, Object>>) fixture.get("tasks");
103	        if (tasks != null) {
104	            for (Map<String, Object> task : tasks) {
105	                // done is optional in a fixture; default to false (OPEN) when absent.
106	                Object done = task.get("done");
107	                jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
108	                        ((Number) task.get("id")).longValue(),
109	                        ((Number) task.get("projectId")).longValue(), task.get("title"),
110	                        done != null && Boolean.parseBoolean(done.toString()));
111	            }
112	        }
113	        List<Map<String, Object>> notes = (List<Map<String, Object>>) fixture.get("notes");
114	        if (notes != null) {
115	            long maxId = 0;
116	            for (Map<String, Object> note : notes) {
117	                long id = ((Number) note.get("id")).longValue();
118	                maxId = Math.max(maxId, id);
119	                // `at` is an ISO instant (e.g. "2026-01-05T09:00:00Z"); store it as a UTC
120	                // timestamp so notes sort newest-first by the instant they were written.
121	                jdbc.update("INSERT INTO notes (id, target_type, target_id, note_text, at)"
122	                        + " VALUES (?, ?, ?, ?, ?)",
123	                        id, note.get("targetType"),
124	                        ((Number) note.get("targetId")).longValue(), note.get("text"),
125	                        java.time.OffsetDateTime.ofInstant(
126	                                java.time.Instant.parse(note.get("at").toString()),
127	                                java.time.ZoneOffset.UTC));
128	            }
129	            // Explicit-id inserts don't advance H2's IDENTITY counter, so a later JPA save() would
130	            // regenerate a seeded id and collide. Restart the counter past the seeded ids.
131	            if (maxId > 0) {
132	                jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxId + 1));
133	            }
134	        }
135	        List<Map<String, Object>> tags = (List<Map<String, Object>>) fixture.get("tags");
136	        if (tags != null) {
137	            for (Map<String, Object> tag : tags) {
138	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
139	                jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
140	                        ((Number) tag.get("id")).longValue(), tag.get("name"));
141	            }
142	        }
143	        List<Map<String, Object>> projectTags =
144	                (List<Map<String, Object>>) fixture.get("projectTags");
145	        if (projectTags != null) {
146	            for (Map<String, Object> link : projectTags) {
147	                // The join row's own id is IDENTITY-generated; the fixture names only the pair.
148	                jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
149	                        ((Number) link.get("projectId")).longValue(),
150	                        ((Number) link.get("tagId")).longValue());
151	            }
152	        }
153	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
154	        if (invoices != null) {
155	            for (Map<String, Object> invoice : invoices) {
156	                // status is optional in a fixture; default to UNPAID (matching Flyway V5) when absent.
157	                Object status = invoice.get("status");
158	                // issuedDate/dueDate are optional; fall back to the Flyway V7 column defaults when absent.
159	                Object issuedDate = invoice.get("issuedDate");
160	                Object dueDate = invoice.get("dueDate");
161	                // An invoice is built from line items (Flyway V13). Its amount is the worked-out sum
162	                // of qty * unitPrice across them (zero when there are none yet) — a fixture no longer
163	                // types a figure, it lists what is charged. (An explicit `amount` still wins if a
164	                // fixture gives one, for back-compatibility with lump-sum invoices.)
165	                List<Map<String, Object>> lineItems =
166	                        (List<Map<String, Object>>) invoice.get("lineItems");
167	                java.math.BigDecimal amount = java.math.BigDecimal.ZERO;
168	                if (lineItems != null) {
169	                    for (Map<String, Object> line : lineItems) {
170	                        java.math.BigDecimal unitPrice =
171	                                new java.math.BigDecimal(line.get("unitPrice").toString());
172	                        int qty = ((Number) line.get("qty")).intValue();
173	                        amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
174	                    }
175	                }
176	                if (invoice.get("amount") != null) {
177	                    amount = new java.math.BigDecimal(invoice.get("amount").toString());
178	                }
179	                long invoiceId = ((Number) invoice.get("id")).longValue();
180	                jdbc.update("INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
181	                        + " VALUES (?, ?, ?, ?, COALESCE(?, CURRENT_DATE),"
182	                        + " COALESCE(?, DATEADD('DAY', 30, CURRENT_DATE)))",
183	                        invoiceId,
184	                        ((Number) invoice.get("projectId")).longValue(),
185	                        amount,
186	                        status != null ? status.toString() : "UNPAID",
187	                        issuedDate != null ? java.sql.Date.valueOf(issuedDate.toString()) : null,
188	                        dueDate != null ? java.sql.Date.valueOf(dueDate.toString()) : null);
189	                if (lineItems != null) {
190	                    for (Map<String, Object> line : lineItems) {
191	                        jdbc.update("INSERT INTO invoice_line_items"
192	                                + " (id, invoice_id, description, qty, unit_price) VALUES (?, ?, ?, ?, ?)",
193	                                ((Number) line.get("id")).longValue(), invoiceId,
194	                                line.get("description"), ((Number) line.get("qty")).intValue(),
195	                                new java.math.BigDecimal(line.get("unitPrice").toString()));
196	                    }
197	                }
198	            }
199	        }
200	        List<Map<String, Object>> payments = (List<Map<String, Object>>) fixture.get("payments");
201	        if (payments != null) {
202	            long maxId = 0;
203	            for (Map<String, Object> payment : payments) {
204	                long id = ((Number) payment.get("id")).longValue();
205	                maxId = Math.max(maxId, id);
206	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
207	                jdbc.update("INSERT INTO payments (id, invoice_id, amount, paid_date)"
208	                        + " VALUES (?, ?, ?, ?)",
209	                        id,
210	                        ((Number) payment.get("invoiceId")).longValue(),
211	                        new java.math.BigDecimal(payment.get("amount").toString()),
212	                        java.sql.Date.valueOf(payment.get("date").toString()));
213	            }
214	            // Explicit-id inserts don't advance H2's IDENTITY counter, so a later JPA save() would
215	            // regenerate a seeded id and collide. Restart the counter past the seeded ids.
216	            if (maxId > 0) {
217	                jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + (maxId + 1));
218	            }
219	        }
220	    }
221	}
