1	import { Fragment, createElement } from 'react';
2	import type { ComponentType, ReactElement } from 'react';
3	import { forSlot } from './registry';
4	
5	// ── Slots: how features add UI without anything being edited ──────────────────────────────────
6	// A SLOT is a region of the UI that features fill. Whatever renders a region never lists what goes
7	// in it, so adding a panel, a table column, a row action, a toolbar control or a nav link is a NEW
8	// FILE and nothing existing is touched.
9	//
10	//   1. declare a region  ->  slots/defs/projectDetail.ts
11	//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
12	//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
13	//   3. fill it           ->  features/projects/notes.slot.tsx
14	//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
15	//
16	// This file, slots/registry.ts and slots/discover.ts are the mechanism — do not edit them. ADD a
17	// file under slots/defs/ to declare a new region.
18	
19	export type Contribution<Ctx> = {
20	  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
21	  order?: number;
22	  Component: ComponentType<Ctx>;
23	};
24	
25	export type SlotDef<Ctx extends object> = {
26	  id: string;
27	  /** Renders the region. Its props ARE the context handed to every contribution. */
28	  Slot: (ctx: Ctx) => ReactElement;
29	  /** A feature wraps its contribution in this, to be typed against the region's context. */
30	  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
31	};
32	
33	export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
34	  return {
35	    id,
36	    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
37	    // row actions are slots too), where a stray <div> would be invalid markup.
38	    Slot: (ctx: Ctx) =>
