      data-testid={`invoice-cancel-${invoice.id}`}
      disabled={voidInvoice.isPending}
      onClick={() => voidInvoice.mutate({ id: invoice.id })}
    >
      Cancel
    </button>
  );
}

export const contribution = InvoiceRow.fill({ order: 20, Component: CancelInvoice });

